<template>
  <section class="profile-view exception-mobile">
    <div class="page-title"><div><small>FIELD CONTROL / ANDON</small><h1>现场异常</h1><p>扫码之外，现场问题也必须有负责人、截止时间和关闭证据。</p></div><button class="text-back" type="button" @click="$emit('close')">返回工作台</button></div>

    <div class="exception-mobile-kpis"><div><small>未关闭</small><b>{{ summary.openExceptions ?? 0 }}</b></div><div><small>关键</small><b class="danger-text">{{ summary.criticalExceptions ?? 0 }}</b></div><div><small>逾期动作</small><b class="warning-text">{{ summary.overdueActions ?? 0 }}</b></div></div>
    <div class="exception-mobile-actions"><button v-for="filter in filters" :key="filter.key" type="button" :class="{ active: activeFilter === filter.key }" @click="activeFilter = filter.key">{{ filter.label }}</button><button class="report-exception-button" type="button" @click="showForm = !showForm"><AppIcon name="plus" :size="13" />上报异常</button></div>

    <div v-if="showForm" class="operation-card exception-form-card"><div class="operation-card-heading"><div><span class="result-kicker">NEW ANDON EVENT</span><h3>上报现场异常</h3></div><button type="button" @click="showForm = false"><AppIcon name="close" :size="17" /></button></div><label class="full-field">异常标题<input v-model.trim="form.title" placeholder="例如：扫码器连续失败" /></label><div class="form-grid"><label>分类<select v-model="form.category"><option value="PROCESS">生产过程</option><option value="MATERIAL">物料齐套</option><option value="QUALITY">质量风险</option><option value="EQUIPMENT">设备异常</option><option value="SAFETY">安全事件</option></select></label><label>优先级<select v-model="form.priority"><option value="LOW">低</option><option value="MEDIUM">中</option><option value="HIGH">高</option><option value="CRITICAL">关键</option></select></label><label>关联工单<input v-model.trim="form.workOrderNo" placeholder="可选" /></label><label>影响数量<input v-model.number="form.impactQty" type="number" min="0" /></label></div><label class="full-field">现场描述<textarea v-model.trim="form.description" rows="3" placeholder="记录现场事实、影响范围和临时措施"></textarea></label><p v-if="error" class="inline-error">{{ error }}</p><button class="submit-operation" type="button" :disabled="saving" @click="createException">{{ saving ? '提交中…' : '提交并进入责任闭环' }}</button></div>

    <div class="exception-mobile-list"><article v-for="item in filteredExceptions" :key="item.id" class="exception-mobile-card" :class="{ expanded: activeId === item.id }"><button class="exception-card-main" type="button" @click="toggle(item)"><div class="exception-card-top"><span :class="['exception-priority', `priority-${String(item.priority).toLowerCase()}`]">{{ priorityLabel(item.priority) }}</span><span class="exception-status">{{ statusLabel(item.status) }}</span></div><h3>{{ item.title }}</h3><p>{{ item.description }}</p><div class="exception-card-meta"><span>{{ item.exception_no }}</span><span>{{ item.equipment_code || item.work_order_no || item.category }}</span><span :class="{ 'danger-text': isOverdue(item) }">截止 {{ formatDate(item.due_at) }}</span></div></button><div v-if="activeId === item.id" class="exception-mobile-detail"><div class="detail-metrics"><span><small>责任人</small><b>{{ item.owner_code || '待分派' }}</b></span><span><small>未完成动作</small><b>{{ item.open_action_count || 0 }}</b></span><span><small>影响数量</small><b>{{ item.impact_qty || 0 }}</b></span></div><div v-if="detailActions.length" class="mobile-action-list"><div v-for="action in detailActions" :key="action.id" class="mobile-action-row"><span :class="['action-marker', { done: action.status === 'COMPLETED' }]">{{ action.status === 'COMPLETED' ? '✓' : '!' }}</span><div><b>{{ action.action_description }}</b><small>{{ action.owner_code || '待分派' }} · {{ formatDate(action.due_at) }}</small></div><button v-if="action.status !== 'COMPLETED'" type="button" @click.stop="completeAction(action)">完成</button></div></div><div class="mobile-action-create"><input v-model="actionText" placeholder="添加围堵 / 根因 / 恢复动作" @keyup.enter="addAction" /><button type="button" :disabled="!actionText.trim()" @click="addAction">添加</button></div><div class="exception-detail-buttons"><button v-if="nextStatus(item.status)" type="button" @click="transition(item)">{{ nextStatusLabel(item.status) }}</button><button type="button" @click="toggle(item)">收起</button></div></div></article><div v-if="!filteredExceptions.length" class="empty-operation">暂无匹配异常</div></div>
  </section>
</template>

<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import AppIcon from './AppIcon.vue'
import { request } from '../api'

defineEmits(['close'])
const summary = ref({}); const exceptions = ref([]); const activeFilter = ref('ALL'); const activeId = ref(null); const detailActions = ref([]); const actionText = ref(''); const showForm = ref(false); const saving = ref(false); const error = ref('')
const form = ref({ title: '', category: 'PROCESS', priority: 'MEDIUM', workOrderNo: '', impactQty: 0, description: '' })
const filters = [{ key: 'ALL', label: '全部' }, { key: 'OPEN', label: '待处理' }, { key: 'CRITICAL', label: '关键' }, { key: 'OVERDUE', label: '逾期' }]
const filteredExceptions = computed(() => exceptions.value.filter(item => activeFilter.value === 'ALL' || (activeFilter.value === 'CRITICAL' ? item.priority === 'CRITICAL' : activeFilter.value === 'OVERDUE' ? isOverdue(item) : item.status !== 'CLOSED')))
function statusLabel(value) { return ({ OPEN: '待确认', ACKNOWLEDGED: '已确认', CONTAINED: '已围堵', RESOLVED: '已解决', CLOSED: '已关闭' }[value] || value) }
function priorityLabel(value) { return ({ LOW: '低', MEDIUM: '中', HIGH: '高', CRITICAL: '关键' }[value] || value) }
function nextStatus(status) { return ({ OPEN: 'ACKNOWLEDGED', ACKNOWLEDGED: 'CONTAINED', CONTAINED: 'RESOLVED', RESOLVED: 'CLOSED' }[status] || '') }
function nextStatusLabel(status) { return ({ ACKNOWLEDGED: '确认收到', CONTAINED: '完成围堵', RESOLVED: '标记解决', CLOSED: '关闭异常' }[nextStatus(status)] || '推进状态') }
function formatDate(value) { return value ? String(value).replace('T', ' ').slice(0, 16) : '—' }
function isOverdue(item) { return item.due_at && !['CLOSED', 'RESOLVED'].includes(item.status) && new Date(item.due_at) < new Date() }
async function load() { try { const [summaryData, exceptionData] = await Promise.all([request('/operations/summary'), request('/operations/exceptions')]); summary.value = summaryData || {}; exceptions.value = exceptionData || [] } catch (requestError) { error.value = requestError.message } }
async function toggle(item) { if (activeId.value === item.id) { activeId.value = null; detailActions.value = []; return } activeId.value = item.id; try { const detail = await request(`/operations/exceptions/${item.id}`); detailActions.value = detail.actions || [] } catch (requestError) { error.value = requestError.message } }
async function createException() { if (!form.value.title || !form.value.description) { error.value = '请填写异常标题和现场描述'; return } saving.value = true; error.value = ''; try { await request('/operations/exceptions', { method: 'POST', body: JSON.stringify({ ...form.value, idempotencyKey: `pda-exception-${Date.now()}` }) }); form.value = { title: '', category: 'PROCESS', priority: 'MEDIUM', workOrderNo: '', impactQty: 0, description: '' }; showForm.value = false; await load() } catch (requestError) { error.value = requestError.message } finally { saving.value = false } }
async function transition(item) { const target = nextStatus(item.status); if (!target) return; try { await request(`/operations/exceptions/${item.id}/transition`, { method: 'POST', body: JSON.stringify({ status: target }) }); await load(); const fresh = exceptions.value.find(row => row.id === item.id); if (fresh) await toggle(fresh) } catch (requestError) { error.value = requestError.message } }
async function addAction() { if (!actionText.value.trim() || !activeId.value) return; try { await request(`/operations/exceptions/${activeId.value}/actions`, { method: 'POST', body: JSON.stringify({ actionType: 'CONTAINMENT', actionDescription: actionText.value.trim() }) }); actionText.value = ''; const detail = await request(`/operations/exceptions/${activeId.value}`); detailActions.value = detail.actions || []; await load() } catch (requestError) { error.value = requestError.message } }
async function completeAction(action) { try { await request(`/operations/actions/${action.id}/complete`, { method: 'POST' }); detailActions.value = detailActions.value.map(item => item.id === action.id ? { ...item, status: 'COMPLETED' } : item); await load() } catch (requestError) { error.value = requestError.message } }
watch(activeFilter, load)
onMounted(load)
</script>

<style scoped>
.exception-mobile{padding-top:0}.exception-mobile-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:14px}.exception-mobile-kpis>div{background:#fff;border:1px solid var(--line);border-radius:9px;padding:11px 12px}.exception-mobile-kpis small,.exception-mobile-kpis b{display:block}.exception-mobile-kpis small{font-size:8px;color:#93a3b0}.exception-mobile-kpis b{font-size:20px;color:#2e5575;margin-top:5px}.warning-text{color:#b9823e!important}.exception-mobile-actions{display:flex;gap:6px;align-items:center;margin-bottom:12px;overflow:auto}.exception-mobile-actions button{white-space:nowrap;font-size:9px;color:#8296a8;padding:7px 10px;border-radius:6px}.exception-mobile-actions button.active{background:#dfeeff;color:#2770d4;font-weight:600}.exception-mobile-actions .report-exception-button{margin-left:auto;display:flex;align-items:center;gap:4px;background:#2773d2;color:#fff}.exception-form-card{margin:0 0 12px;padding:13px}.exception-form-card .operation-card-heading{margin-bottom:4px}.exception-mobile-list{display:flex;flex-direction:column;gap:9px}.exception-mobile-card{background:#fff;border:1px solid var(--line);border-radius:11px;overflow:hidden}.exception-mobile-card.expanded{border-color:#a7c9ee;box-shadow:0 5px 16px #2a70c218}.exception-card-main{display:block;width:100%;text-align:left;padding:13px}.exception-card-top{display:flex;justify-content:space-between;align-items:center}.exception-priority,.exception-status{font-size:8px;padding:4px 6px;border-radius:4px}.priority-critical{background:#fff0ed;color:#c75d52}.priority-high{background:#fff4e6;color:#b97b3e}.priority-medium{background:#edf4ff;color:#4780c4}.priority-low{background:#f1f4f7;color:#7e93a4}.exception-status{background:#eef3f7;color:#6e8498}.exception-card-main h3{font-size:13px;color:#304e69;margin:9px 0 5px}.exception-card-main p{font-size:9px;line-height:1.55;color:#8295a5;margin:0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.exception-card-meta{display:flex;justify-content:space-between;gap:5px;border-top:1px solid #edf2f6;margin-top:10px;padding-top:9px;font-size:8px;color:#9aa9b5}.exception-card-meta span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.exception-mobile-detail{background:#f7faff;border-top:1px solid #e5eef7;padding:12px}.detail-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:0;padding:9px 0;border:0}.detail-metrics small,.detail-metrics b{display:block}.detail-metrics small{font-size:8px;color:#93a3b0}.detail-metrics b{font-size:10px;color:#47637b;margin-top:4px}.mobile-action-list{border-top:1px solid #e4edf5}.mobile-action-row{display:flex;align-items:center;gap:7px;padding:9px 0;border-bottom:1px solid #e4edf5}.mobile-action-row .action-marker{width:19px;height:19px;display:grid;place-items:center;border-radius:50%;background:#fff0ed;color:#cb6559;font-size:9px}.mobile-action-row .action-marker.done{background:#e9f8f0;color:#2eaa7b}.mobile-action-row>div{flex:1;min-width:0}.mobile-action-row b,.mobile-action-row small{display:block}.mobile-action-row b{font-size:9px;color:#476179;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.mobile-action-row small{font-size:8px;color:#9aa9b4;margin-top:3px}.mobile-action-row button,.exception-detail-buttons button{font-size:8px;color:#2872cb;padding:5px 7px;border:1px solid #bdd5ec;border-radius:5px}.mobile-action-create{display:flex;gap:6px;margin-top:10px}.mobile-action-create input{height:31px;flex:1;border:1px solid #d8e4ee;border-radius:5px;padding:0 8px;font-size:9px;background:#fff}.mobile-action-create button{background:#2d73d2;color:#fff;border-radius:5px;padding:0 10px;font-size:9px}.exception-detail-buttons{display:flex;gap:7px;margin-top:10px}.exception-detail-buttons button:first-child{background:#eaf3ff;border-color:#bfd8f4}.exception-detail-buttons button:last-child{margin-left:auto;color:#8094a5;border:0}.exception-mobile .full-field textarea{min-height:64px}.exception-mobile .inline-error{margin-top:8px}.exception-mobile .submit-operation{margin-top:9px}.exception-mobile .text-back{white-space:nowrap}@media(max-width:390px){.exception-card-meta{font-size:7px}.exception-mobile-kpis b{font-size:18px}}
</style>
